    name: { de: "Palau de la Música Catalana", hu: "Palau de la Música Catalana", ro: "Palatul Muzicii Catalane", en: "Palau de la Música Catalana"},
    image: "/poi-images/spain-palau-musica-catalana-landmarks-v2.webp",
